        { id: "l30k2", type: "def", front: "القوانين الدستورية (الأساسية) ومرتبتها", back: "مصدر جميع السلطات من تشريعية (تنظيمية) وتنفيذية وقضائية، وينضوي تحتها الدساتير والأنظمة واللوائح المفسرة لها، وهي أعلى من القوانين العادية وسابقة عليها.", bk: false, pg: "169" },
        { id: "l30k3", type: "count", front: "نوعا الأنظمة السعودية", n: 2, lead: "نوعان:", items: ["أساسية: بعضها بأمر ملكي (النظام الأساسي للحكم، والبيعة، ومجلس الوزراء، ومجلس الشورى) وبعضها بمرسوم ملكي (الجنسية، والقضاء) في تصنيف المؤلف", "عادية: غالبيتها بمراسيم ملكية، وإليها تنتمي غالبية الأنظمة السعودية، وأهميتها في وضوحها وتحديدها"], pg: "169" },
        { id: "l30k4", type: "def", front: "إحالة النظام الأساسي للحكم إلى أنظمة أخرى: غايتها وحجمها", back: "غايتها إعطاء مزيد من الوضوح والشرح لمقاصد ما تعرض له بإيجاز، حتى لا يغرق بالكثير من التفاصيل؛ وقد أحالت (54) مادة منه إلى أنظمة محددة ومتنوعة، كنظام هيئة البيعة الذي حدد كيفية اختيار ولي العهد.", bk: false, pg: "169–170" },
        { id: "l30k5", type: "count", front: "عبارات الإحالة في نهاية أغلب مواد النظام الأساسي للحكم (كما مثّل لها الكتاب)", n: 4, lead: "أربع:", items: ["وفق الشريعة الإسلامية", "ويبين النظام", "وبموجب النظام", "وبموجب أحكام النظام"], pg: "170" },
        { id: "l30k6", type: "count", front: "أوجه تشابه النظام الأساسي للحكم مع دساتير الدول في الشكل", n: 4, lead: "أربعة:", items: ["شكل الحكم ونظامه", "اختصاصات رئيس الدولة وصلاحياته", "السلطات الثلاث والعلاقة بينها", "حقوق الدولة والفرد وواجباتهما تجاه الآخر"], pg: "170" },
        { id: "l30k7", type: "count", front: "أمثلة المواضيع التي اكتسبت الطابع الدستوري بمجرد النص عليها (التشابه في المضمون)", n: 5, lead: "خمسة أمثلة:", items: ["الملكيتان الخاصة والعامة", "التعليم", "الرعاية الصحية والاجتماعية", "العمل", "الاهتمام بالآداب والفنون وحماية البيئة"], pg: "170–171" },
        { id: "l30k8", type: "rule", front: "تطابق النظام الأساسي للحكم مع أحكام القانون الدستوري", rule: "جاءت أحكامه ونصوصه، من حيث المبدأ، متطابقة مع أحكام القانون الدستوري وقواعده التي لا تتعارض مع ثوابت الشريعة الإسلامية.", exc: "لكن هذا التطابق لا ينفي خصوصية بعض أحكامه ونصوصه، وهو أمر مسلّم به أثناء صياغة الدساتير.", pg: "171" },
        { id: "l30k9", type: "def", front: "القانون الدستوري الدولي", back: "فرع جديد من فروع القانون العام، أذنت بميلاده مشاركة القانون الدولي العام نظيره القانون الدستوري في معالجة العديد من الأمور، بعد أن اتجه القانون الدولي المعاصر نحو دسترة موضوعاته كحقوق الإنسان واللجوء السياسي.", bk: false, pg: "171" },
        { id: "l30k10", type: "count", front: "أمثلة المبادئ ذات المرجعية الدولية التي دسترها المنظم السعودي", n: 4, lead: "أربعة:", items: ["حق منح اللجوء السياسي", "صيانة وكفالة العديد من الحقوق والحريات العامة", "توفير الأمن والأمان للجميع دون تمييز", "احترام الملكية الخاصة المادية والفكرية"], pg: "172" },
        { id: "l30k11", type: "rule", front: "القانون الدولي رافداً للقانون الدستوري السعودي", rule: "سيظل القانون الدولي بفروعه المتعددة رافداً مهماً للقانون الدستوري السعودي على الدوام.", exc: "شريطة عدم تعارضه مع مبادئه الأساسية، وفي مقدمتها الشريعة الإسلامية.", pg: "172" }
